param([int]$Hours = 24, [string]$OutputPath)
$ErrorActionPreference='Stop';$Start=(Get-Date).AddHours(-$Hours)
$Events=@(Get-WinEvent -FilterHashtable @{LogName='System';StartTime=$Start} -ErrorAction SilentlyContinue|Where-Object{$_.Id -in @(41,1001,4101,6008) -or $_.ProviderName -match 'WHEA|Display|nvlddmkm|BugCheck|Thermal'}|Select-Object TimeCreated,Id,ProviderName,LevelDisplayName,@{n='summary';e={$m=$_.Message-replace '\s+',' ';$m.Substring(0,[Math]::Min(300,$m.Length))}})
$HasUnexpected=[bool]($Events|Where-Object{$_.Id -in @(41,6008)});$HasDirect=[bool]($Events|Where-Object{$_.ProviderName -match 'WHEA|Display|nvlddmkm|BugCheck|Thermal' -or $_.Id -in @(1001,4101)})
$Result=[ordered]@{checked_at=(Get-Date).ToUniversalTime().ToString('o');hours=$Hours;unexpected_shutdown_detected=$HasUnexpected;direct_cause_evidence_detected=$HasDirect;conclusion=if($HasDirect){'A related hardware, driver, thermal, or bugcheck event exists; inspect details.'}elseif($HasUnexpected){'Unexpected shutdown is confirmed, but these events do not prove thermal, driver, or power root cause.'}else{'No matching unexpected shutdown event found in the interval.'};events=$Events}
$Json=$Result|ConvertTo-Json -Depth 5;if($OutputPath){$Parent=Split-Path $OutputPath -Parent;if($Parent){New-Item -ItemType Directory -Force -Path $Parent|Out-Null};$Json|Set-Content $OutputPath -Encoding utf8};$Json
